const {chromium}=require('playwright');const assert=require('node:assert/strict');const fs=require('node:fs');
const origin=process.env.QA_ORIGIN||'http://127.0.0.1:8765';const live=origin.startsWith('https');const domain='https://www.levenshtein.net';
const routes=['fancy-text-generator','letras-bonitas','letras-diferentes','schriftgenerator','generador-de-letras','police-d-ecriture','caratteri-speciali','lettertypes','generator-czcionek','krasivyy-shrift','yazi-stilleri','ki-tu-dac-biet','font-henkan','te-shu-zi-ti','font-style','akson-phiset','font-aesthetic'];
(async()=>{fs.mkdirSync('qa-hubs',{recursive:true});const b=await chromium.launch({headless:true});const rows=[];for(const width of [320,390,768,1024,1440]){const ctx=await b.newContext({viewport:{width,height:900}});for(const slug of ['text-tools','unicode-text-tools']){const p=await ctx.newPage();const errors=[];p.on('pageerror',e=>errors.push(String(e)));try{const response=await p.goto(origin+'/'+slug+(live?'':'.html'));assert.equal(response.status(),200);assert.equal(await p.locator('h1').count(),1);assert.equal(await p.locator('h1').innerText(),slug==='text-tools'?'Text Tools':'Unicode Text Tools');assert.equal(await p.locator('link[rel=canonical]').getAttribute('href'),domain+'/'+slug);assert.equal(await p.locator('meta[name=robots]').getAttribute('content'),'noindex,nofollow');const title=await p.title(),desc=await p.locator('meta[name=description]').getAttribute('content');assert(title.length<=60&&title.length>=30);assert(desc.length<=160&&desc.length>=100);assert.equal(await p.locator('meta[property="og:title"]').getAttribute('content'),title);assert.equal(await p.locator('meta[name="twitter:description"]').getAttribute('content'),desc);const graph=JSON.parse(await p.locator('script[type="application/ld+json"]').innerText())['@graph'];const list=graph.find(x=>x['@id']===domain+'/'+slug+(slug==='text-tools'?'#market-links':'#localized-tools'));assert.equal(list.numberOfItems,17);assert.deepEqual(list.itemListElement.map(x=>x.url),routes.map(x=>domain+'/'+x));assert.deepEqual(await p.locator('.hub-directory .lv-tool-card').evaluateAll(ns=>ns.map(n=>n.getAttribute('href'))),routes.map(x=>'/'+x));assert.equal(await p.locator('.hub-directory .lv-tool-card').count(),17);assert.equal(await p.locator('.hub-market-group').count(),3);assert.equal(await p.locator('.lv-tool-grid').first().evaluate(n=>getComputedStyle(n).display),'grid');assert.equal(await p.locator('.lv-tool-card').first().evaluate(n=>getComputedStyle(n).display),'grid');assert(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+2),'horizontal overflow');assert.equal(await p.locator('.lv-posts:empty,.lv-paging:empty').count(),0);assert.deepEqual(await p.locator('.hub-directory a[href]').evaluateAll(ns=>ns.filter(n=>{const u=new URL(n.href,location.href);return /^https?:$/.test(u.protocol)&&u.hostname!==location.hostname&&!n.relList.contains('nofollow')}).map(n=>n.href)),[]);await p.locator('.ux-tool-dropdown summary').click();assert(await p.locator('.ux-tool-menu').isVisible());assert.equal(await p.locator('.ux-tool-menu-grid a').count(),17);await p.locator('.ux-tool-dropdown summary').click();if(slug==='unicode-text-tools'){await p.locator('.hub-questions summary').first().click();assert(await p.locator('.hub-questions details').first().getAttribute('open')!==null);assert.equal(await p.locator('.hub-compact-card').count(),0);}else{assert.equal(await p.locator('.hub-compact-card').count(),17);assert.equal(await p.locator('.hub-category').getAttribute('href'),'/unicode-text-tools');}assert.deepEqual(errors,[]);rows.push({slug,width,status:'PASS'});if([390,1440].includes(width))await p.screenshot({path:'qa-hubs/'+slug+'-'+width+'.png',fullPage:true});}catch(e){rows.push({slug,width,status:'FAIL',error:String(e),errors});}finally{await p.close()}console.log(JSON.stringify(rows.at(-1)));}await ctx.close();}
await b.close();fs.writeFileSync('qa-hubs/results.json',JSON.stringify(rows,null,2));if(rows.some(x=>x.status!=='PASS'))process.exitCode=1;})().catch(e=>{console.error(e);process.exitCode=1});